package com.lqq.supportflow.knowledge.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.lqq.supportflow.knowledge.domain.*; import java.time.Instant; import org.springframework.stereotype.Component;
@Component public class MyBatisKnowledgeBaseAdapter implements KnowledgeBasePort { private final KnowledgeBaseMapper mapper; public MyBatisKnowledgeBaseAdapter(KnowledgeBaseMapper mapper){this.mapper=mapper;} public KnowledgeBase create(Long tenantId,String name,String description){Instant now=Instant.now();KnowledgeBaseEntity e=new KnowledgeBaseEntity();e.tenantId=tenantId;e.name=name;e.description=description;e.status="ACTIVE";e.version=1L;e.createdAt=now;e.updatedAt=now;mapper.insert(e);return base(e);} public java.util.List<KnowledgeBase> list(Long tenantId){return mapper.selectList(new QueryWrapper<KnowledgeBaseEntity>().eq("tenant_id",tenantId).eq("status","ACTIVE").orderByAsc("created_at")).stream().map(this::base).toList();} public java.util.Optional<KnowledgeBase> findById(Long tenantId,Long knowledgeBaseId){return java.util.Optional.ofNullable(mapper.selectOne(new QueryWrapper<KnowledgeBaseEntity>().eq("id",knowledgeBaseId).eq("tenant_id",tenantId).eq("status","ACTIVE"))).map(this::base);} public boolean belongsTo(Long tenantId,Long knowledgeBaseId){return findById(tenantId,knowledgeBaseId).isPresent();} private KnowledgeBase base(KnowledgeBaseEntity entity){return new KnowledgeBase(entity.id,entity.name,entity.description,entity.status,entity.version==null?1L:entity.version);}}
